# qx2_range_arith :: (0, 1, 5)
def qx2_range_arith(lo, hi, n):
    if n <= 1:
        return [lo]
    step = (hi - lo) / (n - 1)
    return [lo + i * step for i in range(n)]

if __name__ == '__main__':
    print(qx2_range_arith((0, 1, 5)))

